public static async Task<Dictionary<int, int>> GetViewsByBlogIdAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into blogGroup
        select new { BlogId = blogGroup.Key, TotalViews = blogGroup.Sum(p => p.Views) };

    var totals = await query.ToListAsync(cancellationToken);

    return totals.ToDictionary(t => t.BlogId, t => t.TotalViews);
}
```

